<script setup lang="ts">
import { onMounted, ref } from "vue"; import { onBeforeRouteLeave, useRoute, useRouter } from "vue-router"; import { getCustomer, updateCustomer, type CustomerInput } from "../api";
const route = useRoute(); const router = useRouter(); const form = ref<CustomerInput>({ displayName: "", email: "" }); const original = ref(""); const error = ref(""); const saving = ref(false);
onMounted(async () => { const customer = await getCustomer(String(route.params.id)); form.value = { displayName: customer.displayName, email: customer.email ?? "", phone: customer.phone ?? undefined, address: customer.address ?? undefined, taxId: customer.taxId ?? undefined, internalNotes: customer.internalNotes ?? undefined, tags: customer.tags }; original.value = JSON.stringify(form.value); });
onBeforeRouteLeave(() => !saving.value && JSON.stringify(form.value) !== original.value ? window.confirm("Hay cambios sin guardar. Deseas salir?") : true);
async function save(): Promise<void> { saving.value = true; try { await updateCustomer(String(route.params.id), form.value); void router.push({ name: "customers.detail.general", params: { id: route.params.id } }); } catch (reason) { error.value = (reason as Error).message; } finally { saving.value = false; } }
</script>
<template><form class="entity-form" @submit.prevent="save"><header><div><p class="eyebrow">CRM</p><h1>Editar cliente</h1></div></header><fieldset><legend>Datos de contacto</legend><label>Nombre<input v-model="form.displayName" required /></label><label>Email<input v-model="form.email" type="email" required /></label><label>Telefono<input v-model="form.phone" /></label><label>Direccion<input v-model="form.address" /></label><label>NIF/DNI<input v-model="form.taxId" /></label></fieldset><fieldset><legend>Notas internas</legend><label>Notas<textarea v-model="form.internalNotes" rows="5" /></label></fieldset><p v-if="error" class="feedback error">{{ error }}</p><footer><button class="secondary" type="button" @click="router.back()">Cancelar</button><button :disabled="saving">Guardar cambios</button></footer></form></template>